import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.Cz0TtJv6.js";const m=JSON.parse('{"title":"For AI agents","description":"Playbook so coding agents can install DLMM Bot for a human — Railway easy path, secrets, terms, and llms.txt links.","frontmatter":{"title":"For AI agents","description":"Playbook so coding agents can install DLMM Bot for a human — Railway easy path, secrets, terms, and llms.txt links."},"headers":[],"relativePath":"agents.md","filePath":"agents.md","lastUpdated":null}'),l={name:"agents.md"};function o(n,e,i,d,h,p){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="for-ai-agents" tabindex="-1">For AI agents <a class="header-anchor" href="#for-ai-agents" aria-label="Permalink to &quot;For AI agents&quot;">​</a></h1><p>You are installing <strong>DLMM Bot</strong> for a human operator. Prefer the <strong>Easy (Railway)</strong> path unless they already have a VPS and ask for Advanced.</p><p class="cta-row"><a class="doc-btn" href="https://dlmmbot.com/llms.txt" target="_blank" rel="noreferrer">llms.txt</a><a class="doc-btn ghost" href="https://dlmmbot.com/llms-full.txt" target="_blank" rel="noreferrer">llms-full.txt</a><a class="doc-btn ghost" href="./easy">Easy setup</a></p><h2 id="read-these-first" tabindex="-1">Read these first <a class="header-anchor" href="#read-these-first" aria-label="Permalink to &quot;Read these first&quot;">​</a></h2><ol><li><a href="https://dlmmbot.com/llms.txt" target="_blank" rel="noreferrer">https://dlmmbot.com/llms.txt</a> — short map (URLs + product facts)</li><li><a href="https://dlmmbot.com/llms-full.txt" target="_blank" rel="noreferrer">https://dlmmbot.com/llms-full.txt</a> — fuller summary</li><li>This page + <a href="./easy">Easy setup</a></li><li><a href="./terms">Terms &amp; risk waiver</a> — human must accept in the dashboard; software is as-is, they can lose 100%</li></ol><p>Do <strong>not</strong> invent env vars, weaken live gates, commit secrets, or put a main wallet into the bot.</p><h2 id="human-paste-prompt-optional" tabindex="-1">Human paste prompt (optional) <a class="header-anchor" href="#human-paste-prompt-optional" aria-label="Permalink to &quot;Human paste prompt (optional)&quot;">​</a></h2><p>If the human only gives you a short message, ask them to paste this (or treat it as your standing brief):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Install DLMM Bot for me on Railway (easy path).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Read https://dlmmbot.com/llms.txt and https://dlmmbot.com/llms-full.txt,</span></span>
<span class="line"><span>then follow https://dlmmbot.com/setup/agents and https://dlmmbot.com/setup/easy.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rules: paper mode first, burner wallet only, never commit .env or keys,</span></span>
<span class="line"><span>require Terms acceptance in the dashboard, do not flip live unless I explicitly ask.</span></span>
<span class="line"><span>Tell me every URL and secret I must create myself (Railway, Helius, Jupiter).</span></span></code></pre></div><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>A running <strong>paper</strong> farmer + public HTTPS dashboard where the human finishes secrets in the setup wizard.</p><p>Live mode is <strong>out of scope</strong> unless they explicitly ask — and then both <code>FARMER_MODE=live</code> and <code>[exec] mode = &quot;live&quot;</code> are required.</p><h2 id="hard-rules" tabindex="-1">Hard rules <a class="header-anchor" href="#hard-rules" aria-label="Permalink to &quot;Hard rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Do</th><th>Don&#39;t</th></tr></thead><tbody><tr><td>Paper first</td><td>Flip live without an explicit ask</td></tr><tr><td>Burner wallet only</td><td>Import their main / cold wallet</td></tr><tr><td>Volume at <code>/app/data</code> on Railway</td><td>Let Settings wipe on redeploy (no volume)</td></tr><tr><td>Keep keys in the dashboard / volume</td><td>Commit <code>.env</code>, keys, or <code>DASH_TOKEN</code> to git</td></tr><tr><td>One bot process per wallet/DB</td><td>Run two farmers against the same wallet</td></tr><tr><td>Point them at <a href="./terms">Terms</a></td><td>Skip or auto-click Terms for them without disclosure</td></tr></tbody></table><h2 id="recommended-path-—-railway" tabindex="-1">Recommended path — Railway <a class="header-anchor" href="#recommended-path-—-railway" aria-label="Permalink to &quot;Recommended path — Railway&quot;">​</a></h2><p>Canonical steps: <a href="./easy">Easy setup</a>. Summary:</p><ol><li><strong>Railway</strong> — <a href="https://railway.com?referralCode=SCj9lN" target="_blank" rel="noreferrer">railway.com?referralCode=SCj9lN</a> → New Project → Deploy from GitHub → <code>CryptoGnome/dlmmbot</code> (or their fork). One service. Build/start come from <code>railway.toml</code>.</li><li><strong>Volume</strong> — mount <code>/app/data</code>. Redeploy once after attaching.</li><li><strong>Domain</strong> — Networking → Generate domain.</li><li><strong>Dash token</strong> — from deploy logs (<code>[railway] generated DASH_TOKEN=…</code>) or a Railway variable. Open <code>https://&lt;domain&gt;/?token=…</code>. Persist <code>DASH_TOKEN</code> as a Railway variable so it does not rotate.</li><li><strong>Wizard</strong> — human accepts Terms, pastes RPC + Jupiter (+ optional GMGN), creates/imports an encrypted <strong>burner</strong>, stays on <strong>paper</strong>.</li></ol><h3 id="secrets-the-human-must-create" tabindex="-1">Secrets the human must create <a class="header-anchor" href="#secrets-the-human-must-create" aria-label="Permalink to &quot;Secrets the human must create&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Required</th><th>Where</th></tr></thead><tbody><tr><td><code>RPC_URL</code></td><td>Yes</td><td><a href="https://dashboard.helius.dev/signup" target="_blank" rel="noreferrer">Helius</a> mainnet HTTPS URL</td></tr><tr><td><code>JUPITER_API_KEY</code></td><td>Before live (get it in paper too)</td><td><a href="https://developers.jup.ag/portal" target="_blank" rel="noreferrer">Jupiter Portal</a></td></tr><tr><td><code>GMGN_API_KEY</code></td><td>Optional</td><td><a href="https://gmgn.ai/ai" target="_blank" rel="noreferrer">gmgn.ai/ai</a> — <a href="./api-keys">API keys</a></td></tr><tr><td>Burner wallet</td><td>For live (paper can wait)</td><td>Dashboard wizard — create or Phantom import</td></tr></tbody></table><p>Full signup steps: <a href="./api-keys">API keys</a>.</p><h2 id="advanced-path-only-if-asked" tabindex="-1">Advanced path (only if asked) <a class="header-anchor" href="#advanced-path-only-if-asked" aria-label="Permalink to &quot;Advanced path (only if asked)&quot;">​</a></h2><p><a href="./advanced">Advanced setup</a>: Node 20+, clone <code>CryptoGnome/dlmmbot</code>, <code>npm install</code>, <code>data/config.toml</code> + <code>data/.env</code>, <code>npm run run</code> / PM2. Suggested VPS: <a href="https://www.vultr.com/?ref=9917878-9J" target="_blank" rel="noreferrer">Vultr</a> (~2 vCPU / 4 GB / 80 GB / Ubuntu 24.04).</p><h2 id="after-install-—-verify" tabindex="-1">After install — verify <a class="header-anchor" href="#after-install-—-verify" aria-label="Permalink to &quot;After install — verify&quot;">​</a></h2><ul><li>Dashboard loads with the token</li><li>Terms accepted (wizard or TermsGate)</li><li>Mode shows <strong>PAPER</strong></li><li>Heartbeat / farmer process healthy after first ticks</li><li>Wiki / Settings open without errors</li></ul><p>Useful ops: <a href="./dashboard">Dashboard guide</a>, <a href="./cli">CLI</a> (<code>status</code>, <code>halt</code>, <code>pause</code>), <a href="./faq">FAQ</a>.</p><h2 id="going-live-only-if-explicitly-requested" tabindex="-1">Going live (only if explicitly requested) <a class="header-anchor" href="#going-live-only-if-explicitly-requested" aria-label="Permalink to &quot;Going live (only if explicitly requested)&quot;">​</a></h2><ol><li>Paper looked sane; burner funded</li><li>Helius + Jupiter set</li><li>Set <strong>both</strong> <code>FARMER_MODE=live</code> and <code>[exec] mode = &quot;live&quot;</code></li><li>Restart / redeploy</li><li>One process per wallet</li></ol><p>See <a href="./risk">Risk &amp; sizing</a>. Usage fee on live wins: <a href="./fees">Fees</a>.</p><h2 id="machine-readable-indexes" tabindex="-1">Machine-readable indexes <a class="header-anchor" href="#machine-readable-indexes" aria-label="Permalink to &quot;Machine-readable indexes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://dlmmbot.com/llms.txt" target="_blank" rel="noreferrer">llms.txt</a></td><td>Link map + one-liners — start here</td></tr><tr><td><a href="https://dlmmbot.com/llms-full.txt" target="_blank" rel="noreferrer">llms-full.txt</a></td><td>Longer product / deploy / safety summary</td></tr></tbody></table><p>Repo mirrors: <a href="https://github.com/CryptoGnome/dlmmbot/blob/main/llms.txt" target="_blank" rel="noreferrer"><code>llms.txt</code></a>, <a href="https://github.com/CryptoGnome/dlmmbot/blob/main/llms-full.txt" target="_blank" rel="noreferrer"><code>llms-full.txt</code></a>.</p><h2 id="link-checklist" tabindex="-1">Link checklist <a class="header-anchor" href="#link-checklist" aria-label="Permalink to &quot;Link checklist&quot;">​</a></h2><div class="ref-list"><a href="https://dlmmbot.com/llms.txt">llms.txt <span>short agent map</span></a><a href="https://dlmmbot.com/llms-full.txt">llms-full.txt <span>full agent summary</span></a><a href="./easy">Easy — Railway <span>preferred install</span></a><a href="./api-keys">API keys <span>Helius, Jupiter, GMGN</span></a><a href="./terms">Terms &amp; waiver <span>required in dashboard</span></a><a href="./advanced">Advanced <span>local / VPS / PM2</span></a><a href="./dashboard">Dashboard <span>wizard, HALT, Settings</span></a><a href="https://github.com/CryptoGnome/dlmmbot">GitHub <span>CryptoGnome/dlmmbot</span></a></div>`,33)])])}const u=t(l,[["render",o]]);export{m as __pageData,u as default};
